#include <iostream>

int main() {
    const int age = 67;
    const bool isMember = false;
    const double total = 80.0;
    if (age >= 65 && total >= 50) {
        std::cout << "Senior discount\n";
    }
    if (isMember || total > 100) {
        std::cout << "Free shipping\n";
    }
    if (!isMember) {
        std::cout << "Join today\n";
    }
    return 0;
}

example.code:
#include <iostream>

int main() {
    const int n = 142;
    const char c = 'g';
    std::cout << std::boolalpha;
    std::cout << (n >= 1 && n <= 100) << '\n';
    std::cout << (n % 2 == 0) << '\n';
    std::cout << (c >= 'a' && c <= 'z') << '\n';
    if (n % 5) {
        std::cout << n << " is not a multiple of 5\n";
    }
    return 0;
}

