practice.solution:
#include <iostream>

int main() {
    const int year = 2023;
    const char grade = 'B';
    std::cout << std::boolalpha;
    std::cout << (year >= 2000 && year <= 2099) << '\n';
    std::cout << (year % 4 == 0) << '\n';
    std::cout << (grade >= 'A' && grade <= 'Z') << '\n';
    if (year % 100) {
        std::cout << year << " is not a century year\n";
    }
    return 0;
}
